const date = now.toISOString().slice(0,10);
const dayName = now.toLocaleDateString('en-US', { weekday: 'long', timeZone: 'America/New_York' });
return [{ json: {
  dryRun: true,
  date,
  dayName,
  podcastDir: `/tmp/podcast-${date}`
} }];

parameters.query:
SELECT COALESCE(
  (SELECT episode FROM podcast_episodes WHERE date = $1),
  (SELECT COALESCE(MAX(episode),0)+1 FROM podcast_episodes)
) AS episode;

