const cfg = $('Config').first().json;
const episode = $input.first().json.episode;
return [{ json: { ...cfg, episode } }];

const cfg = $('Merge Episode + Config').first().json;
const raw0 = $input.first().json;
const hits = raw0.hits || (raw0.body && raw0.body.hits) || [];
const seen = new Set();
const stories = [];
for (const h of hits) {
  const url = h.url || `https://news.ycombinator.com/item?id=${h.objectID}`;
  const m = /^https?:\/\/([^\/]+)/i.exec(url);
  if (!m) continue;
  const domain = m[1].toLowerCase().replace(/^www\./, '');
  if (seen.has(domain)) continue;
  seen.add(domain);
  stories.push({
    id: h.objectID,
    title: h.title || 'No title',
    url,
    hn_url: `https://news.ycombinator.com/item?id=${h.objectID}`,
    score: h.points || 0,
    comments: h.num_comments || 0,
    created_at: h.created_at || ''
  });
  if (stories.length >= 10) break;
}
if (stories.length < 5) throw new Error(`only ${stories.length} stories (<5)`);
const storiesJson = JSON.stringify(stories, null, 2);
const metadataJson = JSON.stringify({ episode: cfg.episode, date: cfg.date }, null, 2);
return [{ json: {
  ...cfg,
  storiesJson,
  metadataJson,
  storiesB64: Buffer.from(storiesJson).toString('base64'),
  metadataB64: Buffer.from(metadataJson).toString('base64')
} }];

const cfg = $('Normalize + Dedupe Stories').first().json;
const out = ($input.first().json.stdout || '') + ($input.first().json.stderr || '');
if (out.includes('Topic index unavailable')) throw new Error('PROOF-GATE FAIL: Topic index unavailable — do not publish');
if (!out.includes('[cocoindex] Top trending:')) throw new Error('PROOF-GATE FAIL: no Top trending proof in rank output');
if (!/\[cocoindex\] Loaded \d+ recent podcast story keys for dedupe/.test(out)) throw new Error('PROOF-GATE FAIL: no dedupe proof in rank output');
return [{ json: { ...cfg, rankOutput: out } }];

const cfg = $('Assert Proof-Gate').first().json;
const stories = JSON.parse($('Normalize + Dedupe Stories').first().json.storiesJson);
const titles = stories.map(s => '- ' + s.title).join('\n');
const text = `🟡 Guru's Tech Bytes DRY RUN (n8n) — Ep ${cfg.episode} (${cfg.date})\nNOT published.\nStories:\n${titles}`;
return [{ json: { text } }];

const out = $input.first().json.stdout || '';
let audioUrl = '';
for (const line of out.split('\n')) {
  const t = line.trim();
  if (t.startsWith('{')) { try { audioUrl = JSON.parse(t).audioUrl || ''; if (audioUrl) break; } catch (e) {} }
}
if (!audioUrl) throw new Error('publish produced no audioUrl');
return [{ json: { ...$('Assert Proof-Gate').first().json, audioUrl } }];
